/**
 * @distilled.cloud/stackit -- STACKIT Cloud API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the OpenAPI documents mirrored at
 * `specs/spec-mirror-stackit/specs/`. Everything else in this folder is
 * hand-written.
 *
 * One module per STACKIT product (IaaS, SKE, DNS, Postgres Flex, ...), using
 * that product's latest published OpenAPI version. Auth is a bearer access
 * token minted from a service-account key (`STACKIT_SERVICE_ACCOUNT_KEY_PATH`,
 * `fromServiceAccountKey`) or given directly (`STACKIT_SERVICE_ACCOUNT_TOKEN`);
 * each product's host is rewritten for `STACKIT_REGION` (default `eu01`).
 *
 * @example
 * ```ts
 * import * as Stackit from "@distilled.cloud/stackit";
 *
 * const { zones } = yield* Stackit.dns.listZones({
 *   projectId: "...",
 * });
 * ```
 */
